function pad(n) { return String(n).padStart(2, '0'); }
function normTime(t) {
  if (typeof t === 'number') { const m = Math.round(t * 1440); return pad(Math.floor(m / 60)) + ':' + pad(m % 60); }
  const s = String(t == null ? '' : t).trim();
  const p = s.split(':');
  if (p.length >= 2 && !isNaN(Number(p[0])) && !isNaN(Number(p[1]))) return pad(Number(p[0])) + ':' + pad(Number(p[1]));
  return s;
}
function normDate(d) {
  if (typeof d === 'number') return new Date(Math.round((d - 25569) * 86400000)).toISOString().slice(0, 10);
  return String(d == null ? '' : d).trim().slice(0, 10);
}
function validDate(s) {
  const p = s.split('-');
  if (p.length !== 3 || p[0].length !== 4 || p[1].length !== 2 || p[2].length !== 2) return false;
  const d = new Date(s + 'T00:00:00Z');
  return !isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s;
}
function validTime(s) {
  const p = s.split(':');
  return p.length === 2 && p[0].length === 2 && p[1].length === 2 && !isNaN(Number(p[0])) && !isNaN(Number(p[1])) && Number(p[0]) < 24 && Number(p[1]) < 60;
}
const nowD = new Date(Date.now() + 19800000);
const NOW = { date: nowD.toISOString().slice(0, 10), time: nowD.toISOString().slice(11, 16), stamp: nowD.toISOString().slice(0, 19) + '+05:30' };
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
function dayName(date) { return DAYS[new Date(date + 'T00:00:00Z').getUTCDay()]; }
function toMin(t) { const p = t.split(':'); return Number(p[0]) * 60 + Number(p[1]); }
function fromMin(m) { return pad(Math.floor(m / 60)) + ':' + pad(m % 60); }
function isActive(v) { return String(v).trim().toUpperCase() === 'TRUE'; }
function rowsOf(name) { return $(name).all().map(i => i.json).filter(j => j && Object.keys(j).length > 0 && !j.error); }
function isLive(a) { const s = String(a.status).toUpperCase(); return s === 'CONFIRMED' || s === 'RESCHEDULED'; }
function docView(d) {
  return { doctor_id: String(d.doctor_id), doctor_name: d.doctor_name, specialty: d.specialty, consultation_fee: d.consultation_fee, available_days: String(d.available_days), start_time: normTime(d.start_time), end_time: normTime(d.end_time), slot_duration_minutes: Number(d.slot_duration_minutes) };
}
function gridSlots(d) {
  const v = docView(d); const o = [];
  for (let m = toMin(v.start_time); m + v.slot_duration_minutes <= toMin(v.end_time); m += v.slot_duration_minutes) o.push(fromMin(m));
  return o;
}
function worksOn(d, date) { return String(d.available_days).split(',').map(x => x.trim().toLowerCase()).includes(dayName(date).toLowerCase()); }
function freeSlots(d, date, appts, ignoreId) {
  const taken = appts.filter(a => String(a.doctor_id) === String(d.doctor_id) && normDate(a.appointment_date) === date && isLive(a) && String(a.appointment_id) !== String(ignoreId || '')).map(a => normTime(a.appointment_time));
  return gridSlots(d).filter(s => !taken.includes(s) && !(date === NOW.date && s <= NOW.time));
}
function specMatch(spec, value) {
  const a = String(spec).trim().toLowerCase(); const b = String(value).trim().toLowerCase();
  return b.includes(a) || a.includes(b) || (a.length >= 5 && b.slice(0, 5) === a.slice(0, 5));
}
function newId(prefix) { return prefix + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 5).toUpperCase(); }
function out(o) { return [{ json: o }]; }
function fail(status, message, extra) { return out(Object.assign({ ok: false, status: status, message: message }, extra || {})); }
const inp = $('Tool Input').first().json;
const uid = String(inp.telegram_user_id == null ? '' : inp.telegram_user_id).trim();

function checkSlot(doc, date, time, appts, ignoreId) {
  if (!validDate(date)) return fail('INVALID_DATE', 'The date must be a real calendar date in YYYY-MM-DD format.');
  if (!validTime(time)) return fail('INVALID_TIME', 'The time must be in 24-hour HH:mm format, for example 10:30.');
  if (date < NOW.date || (date === NOW.date && time <= NOW.time)) return fail('PAST_TIME', 'That date and time has already passed. Please choose a future slot.');
  if (!worksOn(doc, date)) return fail('NOT_WORKING_DAY', doc.doctor_name + ' does not work on ' + dayName(date) + '. Working days: ' + doc.available_days + '.');
  if (!gridSlots(doc).includes(time)) return fail('INVALID_SLOT', 'That time is outside working hours or not on a slot boundary. Free slots that day: ' + freeSlots(doc, date, appts, ignoreId).join(', '), { alternatives: freeSlots(doc, date, appts, ignoreId).slice(0, 8) });
  if (!freeSlots(doc, date, appts, ignoreId).includes(time)) return fail('SLOT_TAKEN', 'That slot is not available.', { alternatives: freeSlots(doc, date, appts, ignoreId).slice(0, 8) });
  return null;
}

const docId = String(inp.doctor_id || '').trim();
const date = normDate(inp.appointment_date);
const time = normTime(inp.appointment_time);
if (!uid || !docId || !date || !time) return fail('INVALID_INPUT', 'Doctor, date and time are all required.');
const patient = rowsOf('Read Patients').find(r => String(r.telegram_user_id) === uid);
if (!patient) return fail('NOT_REGISTERED', 'The patient must register (full name and phone) before booking.');
const doc = rowsOf('Read Doctors').find(d => String(d.doctor_id) === docId && isActive(d.active));
if (!doc) return fail('DOCTOR_NOT_FOUND', 'That doctor does not exist or is not active.');
const appts = rowsOf('Read Appointments');
const bad = checkSlot(doc, date, time, appts, '');
if (bad) return bad;
if (appts.some(a => String(a.telegram_user_id) === uid && normDate(a.appointment_date) === date && normTime(a.appointment_time) === time && isLive(a))) return fail('PATIENT_CONFLICT', 'You already have an appointment at this date and time.');
const row = { appointment_id: newId('A'), patient_id: String(patient.patient_id), telegram_user_id: uid, doctor_id: docId, doctor_name: doc.doctor_name, specialty: doc.specialty, appointment_date: date, appointment_time: time, status: 'CONFIRMED', created_at: NOW.stamp, updated_at: NOW.stamp };
return out({ ok: true, row: row, view: { appointment_id: row.appointment_id, doctor_name: row.doctor_name, specialty: row.specialty, appointment_date: date, appointment_time: time, status: 'CONFIRMED', consultation_fee: doc.consultation_fee }, successMessage: 'Appointment booked with ' + doc.doctor_name + ' on ' + date + ' at ' + time + '. Appointment ID ' + row.appointment_id + '.' });

const prev = $('Validate Request').first().json;
const r = $input.first().json;
if (r.error) {
  return [{ json: { status: 'ERROR', message: 'The Google Sheets write failed, so nothing was saved. Please try again later.' } }];
}
return [{ json: { status: 'SUCCESS', message: prev.successMessage, record: prev.view || prev.row } }];
